def find_release_point(b, tx, ty):
    # Function to convert polar coordinates to Cartesian coordinates
    def polar_to_cartesian(r, phi):
        return r * math.cos(phi), r * math.sin(phi)

    # Function to calculate the intersection of a line and the spiral
    def intersection(b, phi, px, py):
        A = b**2 + 1
        B = 2 * (b * (px * math.cos(phi) + py * math.sin(phi)) - px * px - py * py)
        C = px**2 + py**2 - b**2 * phi**2
        discriminant = B**2 - 4 * A * C
        if discriminant < 0:
            return None
        sqrt_discriminant = math.sqrt(discriminant)
        phi1 = (-B - sqrt_discriminant) / (2 * A)
        phi2 = (-B + sqrt_discriminant) / (2 * A)
        if phi1 >= phi and phi1 <= phi + 2 * math.pi:
            return polar_to_cartesian(b * phi1, phi1)
        if phi2 >= phi and phi2 <= phi + 2 * math.pi:
            return polar_to_cartesian(b * phi2, phi2)
        return None

    # Calculate the angle to the target
    theta = math.atan2(ty, tx)

    # Find the intersection points
    p1 = intersection(b, theta, tx, ty)
    p2 = intersection(b, theta + 2 * math.pi, tx, ty)

    # Determine the correct point based on the direction
    if p1 and p2:
        d1 = abs(p1[0] - tx)**2 + abs(p1[1] - ty)**2
        d2 = abs(p2[0] - tx)**2 + abs(p2[1] - ty)**2
        return p1 if d1 < d2 else p2
    elif p1:
        return p1
    elif p2:
        return p2
    else:
        raise ValueError("No valid intersection found")

